#include <iostream>
#include <vector>
#include <algorithm>
#include <ranges>

int main() {
    using namespace std;
    unsigned N, K;
    cin >> N >> K;

    vector<pair<unsigned, unsigned>> cloth(N);
    for (auto&& [L, R] : cloth)
        cin >> L >> R;

    // 右端でソート
    ranges::sort(cloth, {}, [](const auto& p){return p.second;});

    // 二分探索で布を伸ばせる限界を見つける
    unsigned ans{*ranges::partition_point(views::iota(0U, 1000000000U), [K, &cloth](const unsigned x){
        unsigned chosen{}, last{};
        // 区間スケジューリングで布をなるべく多く選ぶ
        for (const auto& [L, R] : cloth) {
            if (last <= L) {
                ++chosen;
                last = R + x + 1; // 右に x だけ伸ばしておく
            }
        }
        // K 枚以上選べたら OK
        return chosen >= K;
    })};

    // 1 以上伸ばせるなら
    if (ans) {
        cout << ans << endl; // それが答え
    } else { // 伸ばせないなら
        cout << -1 << endl; // -1
    }
    return 0;
}
